/* Месяцеслов «Православных» — 05.
   Каждый святой имеет краткое описание; lifeId — полное житие (src/lib/content/lives.ts). */

import type { SaintRec } from "./types";

export const M05: SaintRec[] = [
  { key: "05-01", name: "Прп. Иоанна Солунского (Фессалоникийского), ученика прп. Григория Декаполита", kind: "saint", desc: "Преподобный Иоанн родился в конце VIII века. В юношеском возрасте он стал учеником преподобного Григория Декаполита (&dagger; ок. 820, память 20 ноября) и принял от него иноческий постриг в Солунском монастыре." },
  { key: "05-01", name: "мч. Иоанна Нового из Янины", kind: "saint", desc: "Святой Иоанн родился в 1522 году в бедной христианской семье в деревне Теровон между Яниной и Артой. После смерти родителей, он отправился в Константинополь, который за пятьдесят лет до того был захвачен турками." },
  { key: "05-01", name: "Сщмч. Виссариона Селинина, пресвитера", kind: "saint", desc: "Священномученик Виссарион (Виссарион Мефодиевич Селинин) окончил два класса Владимирской Духовной семинарии и с 1896 года служил псаломщиком во Владимирской епархии." },
  { key: "05-01", name: "прмц. Тамары (Сатси), игумении", kind: "saint", desc: "Преподобномученица Тамара (Сатси) (1876–1942) — в миру Мария, родилась в Эстляндской губернии в лютеранской семье. Святая рано осталась без родителей и воспитывалась в приюте для девочек-сирот при женской православной общине в Иевве." },
  { key: "05-01", name: "Максимовская", year: "1299", kind: "saint", desc: "Максимовская икона Божией Матери написана в 1299 году по видению святителю Максиму, митрополиту Владимирскому (&dagger; 1305, память 6 декабря), который прибыл во Владимир для перенесения из Киева Первосвятительской кафедры." },
  { key: "05-02", name: "Прп. Иоанна Ветхопещерника, иеромонаха", kind: "saint", desc: "Преподобный Иоанн Ветхопещерник назван так потому, что подвизался в VIII веке в Лавре преподобного Харитона (&dagger; ок. 450, память 28 сентября), которая называлась Ветхой, то есть древней, как старшая из палестинских обителей." },
  { key: "05-02", name: "блж. Матроны Московской", kind: "saint", desc: "8 марта (переходящая) - Обр е тение мощей. 8 марта / 23 февраля в невисокосный год, 7 марта / 23 февраля в високосный год Родилась блаженная Матрона (Матрона Димитриевна Никонова) в 1881 году в селе Себино Епифанского уезда (ныне Кимовского района) Тульской губернии.", lifeId: "matrona" },
  { key: "05-02", name: "сщмч. Пафнутия, епископа Иерусалимского", kind: "saint", desc: "Священномученик Пафнутий Иерусалимский был епископом. Он претерпел много страданий от язычников и был мучен огнем, зверями, а затем усечен мечом. Предполагают, что священномученик Пафнутий был египетским епископом и пострадал вместе со мног" },
  { key: "05-02", name: "свт. Георгия исп., епископа Антиохии Писидийской", kind: "saint", desc: "Святитель Георгий Исповедник, епископ Антиохии Писидийской, жил во времена иконоборчества. В молодые годы он принял иночество, прославился святостью жизни и был поставлен епископом Антиохии Писидийской.", lifeId: "georgiy" },
  { key: "05-02", name: "свт. Трифона, патриарха Константинопольского", kind: "saint", desc: "Святитель Трифон, патриарх Константинопольский, с юношеских лет был иноком и отличался кротостью, незлобием, полной покорностью воле Божией, твердой верой и любовью к Церкви." },
  { key: "05-02", name: "прп. Никифора Катавадского, игумена", kind: "saint", desc: "Преподобный Никифор родился в Константинополе в богатой и знатной семье. Его родители, Андрей и Феодора, воспитали сына в христианской вере. После их смерти юный Никифор раздал все свое имение нищим и отправился в Халкидон." },
  { key: "05-02", name: "Свт. Виктора (Островидова), исп., епископа Глазовского", kind: "saint", desc: "Сщисп. Виктор (Островидов), епископ Глазовский, родился в 1875 г. в семье диакона Саратовской губернии. Окончил Казанскую духовную академию, принял монашество в 1903 г." },
  { key: "05-03", name: "Прп. Феодора Трихины", kind: "saint", desc: "Преподобный Феодор Трихина родился в богатой константинопольской семье. В юности он удалился в пустынную обитель во Фракии и принял монашество. Преподобный был строгим постником, носил только одну грубую, колючую власяницу, отчего и был прозван Трихиною, то есть &quot;Власяничным&quot;." },
  { key: "05-03", name: "Прп. Александра Ошевенского, игумена", kind: "saint", desc: "Преподобный Александр Ошевенский родился 17 марта 1427 года в 80 верстах от Белозерска в Вышеозерской волости, за несколько месяцев до кончины преподобного Кирилла Белозерского (&dagger; 9 июня 1427 г.), с которым был связан в последующем духовными узами всю жизнь." },
  { key: "05-03", name: "мч. младенца Гавриила Белостокского", kind: "saint", desc: "Родился 22 марта 1684 г. в деревне Зверки Белостокского уезда Гродненской губернии, в семье благочестивых крестьян Петра и Анастасии. Он рос кротким, незлобивым, заметна была в нем склонность к созерцательному уединению." },
  { key: "05-03", name: "Григория", kind: "saint", desc: "Святитель Григорий, патриарх Антиохийский (573–593), был игуменом монастыря Фаран, находившегося недалеко от Синайской горы. Преподобный отличался пламенной верой, был милостив, сострадателен к согрешавшим, смиренен и незлобив." },
  { key: "05-03", name: "Анастасия I Синаита (599), патриархов Антиохийских", kind: "saint", desc: "Святой Анастасий Синаит I-й, патриарх Антиохийский, начал свой иноческий подвиг на Синайской горе, почему и был назван Синаитом. Он вступил на патриарший престол в 562 году в царствование императора Юстиниана (527–565)." },
  { key: "05-03", name: "прп. Анастасия, игумена Синайской горы", kind: "saint", desc: "Преподобный Анастасий, игумен Синайской горы, родился в конце VI века. В юности он получил прекрасное светское образование, которое завершил изучением Богословия." },
  { key: "05-03", name: "свт. Николая (Велимировича), епископа Охридского и Жичского (1956)", kind: "saint", desc: "Святитель Николай, богоносный отец наших дней, родился в день памяти святителя Наума Охридского в 1880 году. Его родители, крестьяне-фермеры, всегда прекращали работу для ежедневной молитвы и соблюдали церковный постовой и богослужебный круг." },
  { key: "05-03", name: "перенесение мощей мч. Авраамия Болгарского, Владимирского чудотворца (1230)", kind: "saint", desc: "Мученик Авраамий родился в Камской Болгарии (болгары жили между реками Волгою и Камою, впоследствии постепенно утратили свою народность и смешались с победившими их татарами) и воспитан был в магометанской вере, которую исповедовали его соотечественники." },
  { key: "05-03", name: "прав. Тавифы Иоппийской (I)", kind: "saint", desc: "Св. праведная Тавифа, жившая в I веке в Иоппии, принадлежала к христианской общине. После её смерти христиане призвали апостола Петра, находившегося неподалёку." },
  { key: "05-03", name: "Свт. Феодосия (Ганицкого), исп., епископа Коломенского", kind: "saint", desc: "Священноисповедник Феодосий родился 30 июля 1860 года в селе Руда Васильковского уезда Киевской губернии в семье священника Феодора Ганицкого и в крещении был наречен Иоанном." },
  { key: "05-03", name: "Кипрская", year: "392", kind: "saint", desc: "Кипрская икона Божией Матери явилась в 392 году на острове Кипре на месте, где был погребен праведный Лазарь, и была помещена в монастыре Ставруни, устроенном на месте ее чудесного обретения." },
  { key: "05-04", name: "прп. Феодора Санаксарского", kind: "saint", desc: "Преподобный Феодор Санаксарский (в миру дворянин Иван Игнатьевич Ушаков) родился в 1718 году в сельце Бурнаково Романовского уезда Ярославской провинции." },
  { key: "05-04", name: "прав. Алексия Бортсурманского, пресвитера", kind: "saint", desc: "Праведный Алексий Бортсурманский (1762-1848) – священник села Бортсурманы Симбирской губернии, прошедший путь от грешника к великому подвижнику. После видения Ангела с Чашей (1796) полностью изменил жизнь, ежедневно совершая Литургию и соблюдая строгий молитвенный устав." },
  { key: "05-04", name: "свт. Максимиана (Максима), патриарха Константинопольского", kind: "saint", desc: "Святитель Максимиан, патриарх Константинопольский, родился в Риме от богатых и благочестивых родителей. На собственные средства он устраивал гробницы для погребения умерших, прославившихся святостью жизни." },
  { key: "05-04", name: "Сщмч. Иоанна Пригоровского, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился 4 января 1875 года в семье пономаря Черниговской епархии Емельяна Пригоровского. В 1897 году Иван окончил Черниговскую Духовную семинарию и был направлен служить псаломщиком в храм в селе Мостовое Кубанской области." },
  { key: "05-04", name: "св. Николая Писаревского, исп., пресвитера", kind: "saint", desc: "Священноисповедник Николай родился в 1868 году в селе Ягорба Мологского уезда Ярославской губернии в семье священника Павла Писаревского. Окончив Рязанскую Духовную семинарию, он был рукоположен во священника ко храму в родном селе." },
  { key: "05-04", name: "сщмч. Алексия Протопопова, пресвитера", kind: "saint", desc: "Священномученик Алексий родился 15 марта 1880 года в селе Ильинском Бронницкого уезда Московской губернии в семье псаломщика Николая Михайловича Протопопова." },
  { key: "05-05", name: "Прп. Феодора Сикеота, епископа Анастасиупольского", kind: "saint", desc: "Прп. Феодор Сикеот (VI-VII вв.) родился в Малой Азии. Он с детства был отмечен благодатью Божией. С 8 лет начал строгий пост, в 10 лет чудесно исцелился от смертельной болезни." },
  { key: "05-05", name: "Перенесение мощей блгв. кн. Всеволода, во Святом Крещении Гавриила, Новгородского, Псковского", kind: "saint", desc: "Святой благоверный князь Всеволод, в Крещении Гавриил, Псковский, внук Владимира Мономаха, родился и почти всю жизнь прожил в Новгороде, где в 1088–1093 и 1095–1117 годах княжил его отец, святой благоверный князь Мстислав-Феодор Великий (&dagger; 15 апреля 1132)." },
  { key: "05-05", name: "апп. Варфоломея", kind: "saint", desc: "Св. апостол Варфоломей, один из 12 учеников Христа, проповедовал в Сирии, Малой Азии и Индии, где перевел Евангелие по Матфею. В Армении исцелил царскую дочь, обратил многих ко Христу, за что был казнен язычниками ‒ его распяли, с живого содрали кожу и обезглавили (71 г.)." },
  { key: "05-05", name: "Климента, епископа", kind: "saint", desc: "Св. апостол Климент, епископ Сардийский, упомянут апостолом Павлом в Послании к Филиппийцам (Флп.4:3). Святой апостол Климент был епископом в Сардике (в древности богатый город Лидии в Малой Азии)." },
  { key: "05-05", name: "мч. Епиподия Лионского", kind: "saint", desc: "Во время гонений Марка Аврелия (177) язычники города Лиона предали мученической смерти многих лионских христиан и надеялись истребить их всех. Александр и Епиподий, с самого детства связанные узами духовной дружбы, бежали из города и укрылись в предместье у некоей вдовы-христианки." },
  { key: "05-05", name: "прп. Виталия Александрийского", kind: "saint", desc: "Преподобный Виталий, инок монастыря преподобного Серида, пришел в Александрию при святителе Иоанне Милостивом (память 12 ноября), патриархе Александрийском (609–620)." },
  { key: "05-05", name: "сщмч. Платона, епископа Банялукского (1941)", kind: "saint", desc: "Этот великий иерарх Православной Церкви Христовой родился в 1874 году в Белграде. Родители будущего епископа, Елена и Илия, были выходцами из Герцеговины, бедного скалистого края, в котором православная вера и патриотизм ставились превыше всего." },
  { key: "05-05", name: "Сщмч. Евстафия Малаховского, пресвитера", kind: "saint", desc: "Священномученик Евстафий родился 29 марта 1880 года в семье священника Полоцкой епархии Владимира Малаховского. В 1897 году Евстафий окончил Полоцкое духовное училище, в 1900 году – три класса Витебской Духовной семинарии и был назначен учителем в Прудскую церковноприходскую школу Гродненской епархии." },
  { key: "05-05", name: "мч. Димитрия Власенкова", kind: "saint", desc: "Мученик Димитрий родился 15 мая 1880 года в местечке Россасна Горецкого уезда Могилевской губернии [1] в семье крестьянина Емельяна Власенкова, исполнявшего в селе должность волостного старшины." },
  { key: "05-06", name: "Вмч. Георгия Победоносца", kind: "saint", desc: "Вмч. Георгий Победоносец, римский военачальник III-IV веков, родился в Палестине. При императоре Диоклетиане он открыто исповедал свою веру во Христа, раздал имущество бедным и обличил жестокость гонителей.", lifeId: "georgiy" },
  { key: "05-06", name: "Иверской иконы Божией Матери", kind: "icon", desc: "Иверская икона Божией Матери, находящаяся на Афоне , прославилась многими чудесами. Слух о чудотворном образе через паломников распространился по России." },
  { key: "05-06", name: "Мц. царицы Александры Римской", kind: "saint", desc: "Существуют различные жития святой мученицы Александры Римской. Согласно одному из них, святая Александра, супруга императора Диоклетиана, была тайной христианкой." },
  { key: "05-06", name: "прп. Софии (Хотокуриду)", kind: "saint", desc: "В 2003 году в Афинах состоялась большая выставка икон, написанных современными иконописцами. Икона Софии (&dagger; 6 мая 1974) – работа талантливого иконописца Димитрия Хаджиапостола – привлекла особенное внимание посетителей." },
  { key: "05-06", name: "Сщмч. Иоанна Ансерова, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился 8 сентября 1873 года в селе Чарус Касимовского уезда Рязанской губернии в семье пономаря Успенской церкви Дмитрия Максимовича Ансерова и его супруги Елизаветы Акимовны." },
  { key: "05-06", name: "Моздокская (Иверская)", year: "XIII", kind: "saint", desc: "Грузинская царица святая Тамара, жившая в конце XII – начале XIII века, способствовала распространению на Кавказе христианства, воздвигала и снабжала утварью и облачениями множество храмов в горах и ущельях." },
  { key: "05-06", name: "Дубенская (Красногорская)", year: "XVII", kind: "saint", desc: "Во многих публикациях, посвящённых иконам Божией Матери, Дубенской иконой, празднование которой совершается в день Преполовения Пятидесятницы, называют образ, принадлежащий к семейным святыням знаменитого дома князей Острожских (Острозских)." },
  { key: "05-07", name: "Мч. Саввы Стратилата и с ним 70-ти воинов", kind: "saint", desc: "Мученик Савва происходил из готфского племени. Своей храбростью он достиг высокого чина воеводы-стратилата и служил при императоре Аврелиане (270–275)." },
  { key: "05-07", name: "Прп. Саввы Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобный Савва Печерский подвизался в Ближних пещерах Киево-Печерского монастыря в XIII веке. В рукописных святцах, в &quot;Книге о святых&quot; и в каноне службы Киево-Печерским преподобным он называется чудотворцем." },
  { key: "05-07", name: "прп. Алексия, затворника Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобный Алексий, затворник Печерский, подвизался в Ближних пещерах Киево-Печерского монастыря в XIII веке. Мощи его были открыты после 1675 года. Память преподобного Алексия совершается 24 апреля потому, что его мощи почивают рядом с мощами преподобного Саввы Печерского." },
  { key: "05-07", name: "мч. Александра Лионского", kind: "saint", desc: "Во время гонений Марка Аврелия (177) язычники города Лиона предали мученической смерти многих лионских христиан и надеялись истребить их всех. Александр и Епиподий, с самого детства связанные узами духовной дружбы, бежали из города и укрылись в предместье у некоей вдовы-христианки." },
  { key: "05-07", name: "прп. Елисаветы Константинопольской, чудотворицы, игумении", kind: "saint", desc: "Преподобная Елисавета чудотворица была избрана на служение Богу еще до рождения. Ее матери было откровение, что отроковица будет избранным сосудом Святого Духа." },
  { key: "05-07", name: "прп. Фомы юродивого, Сирийского", kind: "saint", desc: "Преподобный Фома Юродивый был иноком одного из монастырей в Кесарии Каппадокийской (Малая Азия). Он нес послушание по сбору милостыни на нужды монастыря." },
  { key: "05-07", name: "свт. Симеона (Стефана) Трансильванского, митрополита (1656)", kind: "saint", desc: "Святитель Симеон (Стефан) Трансильванский (первая половина XVII века — 1656). Учился в академической коллегии в Альба-Юлии. В 1643 году избран митрополитом Трансильванским." },
  { key: "05-07", name: "сщмч. Бранко Добросавлевича, пресвитера (1941)", kind: "saint", desc: "Бранко Добросавлевич родился 4 января 1886 года в городке Скрад. В 1908 году окончил Сремско-Карловацкую духовную семинарию и был рукоположен в диаконский, а затем и в священнический сан." },
  { key: "05-07", name: "Мч. Сергия Архангельского", kind: "saint", desc: "Мученик Сергий родился 4 сентября 1898 года в селении Погост Десятая Пятница Богородского уезда Московской губернии в семье священника Василия Архангельского." },
  { key: "05-07", name: "Молченская", year: "1405", kind: "saint", desc: "Существует две чудотворные иконы под названием Молченская. Одна из них находится в Софрониево-Молченской Богородично-Рождественской пещерной мужской пустыни , другая – в Молченском Рождества Богородицы женском монастыре ." },
  { key: "05-08", name: "Апостола и евангелиста Марка", kind: "saint", desc: "Родился в Иерусалиме, племянник апостола Варнавы. В ночь крестных страданий Христа он следовал за Ним ( Мр.14:51-52 ). Ученик апостола Петра. Основал Церковь в Египте, был первым епископом в Александрии." },
  { key: "05-08", name: "Прп. Сильвестра Обнорского", kind: "saint", desc: "Преподобный Сильвестр Обнорский жил в XIV веке и был современником святителя Алексия, митрополита Московского , и одним из учеников преподобного Сергия Радонежского." },
  { key: "05-08", name: "прп. Василия Поляномерульского (1767)", kind: "saint", desc: "Блаженный старец Василий [1] родился в 1692 году, предположительно в Малороссии. От юности своей он, охваченный божественным желанием, удалялся в пустынные и уединенные места, чтобы приобщиться к равноангельской жизни других подвижников." },
  { key: "05-08", name: "Сщмч. Сергия Рохлецова, пресвитера", kind: "saint", desc: "Священномученик Сергий родился в 1876 году в семье священника Дмитрия Рохлецова, служившего в одном из храмов Великого Устюга. После окончания Духовной семинарии он был рукоположен во священника к церкви великомученицы Параскевы Пятницы, в которой он и прослужил всю жизнь." },
  { key: "05-08", name: "св. Надежды Семеновой, исп.", kind: "saint", desc: "Надежда Васильевна Семёнова родилась 8 сентября 1865 года в городе Воскресенске (ныне город Истра) Звенигородского уезда Московской губернии. Крещена в младенчестве в Вознесенском храме города Воскресенска." },
  { key: "05-08", name: "Цареградская", year: "1071", kind: "saint", desc: "Цареградской называют две значительно отличающихся друг от друга иконы. По преданию, Цареградская икона Божией Матери, память которой празднуется 8 мая (25 апреля по старому стилю), – одна из икон, написанных святым апостолом и евангелистом Лукой." },
  { key: "05-09", name: "Сщмч. Василия, епископа Амасийского", kind: "saint", desc: "Священномученик Василий, епископ Амасийский, жил в начале IV века в понтийском городе Амасии. Он поддерживал и утешал христиан, страдавших от гонений язычников." },
  { key: "05-09", name: "свт. Стефана, епископа Великопермского", kind: "saint", desc: "Святитель Стефан, просветитель Перми, апостол зырян, родился около 1340 года в семье устюжского причетника Симеона. Под влиянием своей благочестивой матери Марии, обладая большими способностями, он с юных лет проявлял необыкновенное усердие" },
  { key: "05-09", name: "Прав. Глафиры девы", kind: "saint", desc: "Священномученик Василий, епископ Амасийский, жил в начале IV века в понтийском городе Амасии. Он поддерживал и утешал христиан, страдавших от гонений язычников." },
  { key: "05-09", name: "прп. Иоанникия Девиченского (XIII)", kind: "saint", desc: "Преподобный Иоанникий Девиченский подвизался в первой половине XV века. Святой был родом из Черногорского приморья. С юности избрал он путь монашеского подвига, рано покинул отчий дом и поселился в пещере на берегу реки Ибар, где, по преданию, в XIV веке жил другой сербский пустынник – преподобный Петр Коришский." },
  { key: "05-09", name: "Собор новомучеников, в Бутове пострадавших", kind: "feast", desc: "В 4-ю субботу по Пасхе Русская Православная Церковь отмечает День памяти Собора новомучеников, в Бутове пострадавших. Это переходящее празднование было внесено в месяцеслов Русской Православной Церкви по благословению Святейшего Патриарха М" },
  { key: "05-10", name: "Ап. от 70-ти и сщмч. Симеона Иерусалимского, сродника Господня", kind: "saint", desc: "Сродник Господень по плоти, сын Клеопы, младшего брата св. Иосифа Обручника , епископ Иерусалимский, управлявший Церковью 40 лет и много потрудившийся в проповеди Евангелия." },
  { key: "05-10", name: "Прп. Стефана, игумена Печерского, епископа Владимиро-Волынского", kind: "saint", desc: "Преподобный Стефан, игумен Печерский, епископ Владимиро-Волынский, с молодых лет подвизался в Киево-Печерской обители под руководством преподобного Феодосия (&dagger; 1074; память 3/16 мая)." },
  { key: "05-10", name: "прав. Евлогия Странноприимца", kind: "saint", desc: "Праведный Евлогий Странноприимец жил в IV веке в Фиваиде. Он нес подвиг служения странникам. Однажды авва Даниил, пресвитер скитский, пошел в Фиваиду, взяв с собою одного из учеников своих." },
  { key: "05-10", name: "прмц. Марии Носовой, послушницы", kind: "saint", desc: "Преподобномученица Мария родилась в 1872 году в селе Дубенька Козельского уезда Калужской губернии в семье крестьянина Павла Носова. В 1893 году она поступила послушницей в Страстной монастырь в Москве, в котором подвизалась до его закрытия" },
  { key: "05-10", name: "сщмч. Иоанна Спасского, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился 3 сентября 1873 года в селе Васильевском Ржевского уезда Тверской губернии в семье псаломщика Николая Спасского. Первоначальное образование Иван получил в Осташковском духовном училище." },
  { key: "05-11", name: "Иасона", kind: "saint", desc: "Апостол Иасон происходил из Тарса (Малая Азия). Он был первым христианином в городе. Апостол Сосипатр был родом из Ахаии. Оба они стали учениками апостола Павла, который даже назвал их своими &quot;сродниками&quot; ( Рим.16,21 )." },
  { key: "05-11", name: "Сосипатра", kind: "saint", desc: "Святой Родион, или Иродион, родственник апостола Павла ( Рим.16,11 ), оставил епископскую кафедру в Патрах, чтобы идти в Рим со святым апостолом Петром." },
  { key: "05-11", name: "мц. Керкиры девы и иных, с ними пострадавших", kind: "saint", desc: "Апостол Иасон происходил из Тарса (Малая Азия). Он был первым христианином в городе. Апостол Сосипатр был родом из Ахаии. Оба они стали учениками апостола Павла, который даже назвал их своими &quot;сродниками&quot; ( Рим.16,21 )." },
  { key: "05-11", name: "Свт. Кирилла, епископа Туровского", kind: "saint", desc: "Святитель Кирилл, епископ Туровский, родился в 30-х годах XII века в городе Турове на реке Припяти у богатых родителей. С малых лет святой Кирилл с усердием читал священные книги и достиг глубокого понимания их." },
  { key: "05-11", name: "Мц. Анны Шашкиной", kind: "saint", desc: "Мученица Анна родилась 13 февраля 1888 года в деревне Пигаскино [1] Пошехонского уезда Ярославской губернии в семье крестьянина Василия Шашкина. Окончив сельскую школу, Анна жила вместе с родителями и со временем намеревалась поступить в монастырь." },
  { key: "05-12", name: "прп. Мемнона Чудотворца, игумена Египетского", kind: "saint", desc: "Преподобный Мемнон чудотворец с юности подвизался в Египетской пустыне. Тяжелыми постническими трудами достигал он победы духа над плотью. Став игуменом одного из египетских монастырей, мудро и осторожно руководил братией." },
  { key: "05-12", name: "прп. Нектария Оптинского", kind: "saint", desc: "Последним соборно избранным оптинским старцем был преподобный Нектарий, ученик скитоначальника преподобного Анатолия (Зерцалова) и преподобного старца Амвросия ." },
  { key: "05-12", name: "Прп. Амфилохия Почаевского (Головатюка)", kind: "saint", desc: "В селе Малая Иловица, что на Шумщине, в многодетной крестьянской семье Варнавы Головатюка 27 ноября 1894 года родился сын, в Святом Крещении названный Иаковом в честь мученика Иакова Персянина." },
  { key: "05-12", name: "свт. Василия Острожского, митрополита (1671)", kind: "saint", desc: "Святитель Василий Острожский – один из самых почитаемых сербских святых. По сей день не прекращаются бесчисленные чудеса исцелений у ковчега с его мощами, находящимися в черногорском монастыре Острог." },
  { key: "05-12", name: "трехсот мучеников, в горах Дудикв а ти и Пап а ти (Турция) пострадавших (XVII–XVIII)", year: "Груз.", kind: "saint", desc: "Триста мучеников грузинских пострадали от рук мусульман в горах Турции Дудиквати и Папати (XVII–XVIII вв.). Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите к" },
  { key: "05-12", name: "Прмц. Афанасии (Лепешкиной), игумении", kind: "saint", desc: "Преподобномученица Афанасия, игумения (в миру Лепёшкина Александра Васильевна), родилась в 1885 году в Москве в семье богатых московских купцов. На протяжении нескольких поколений эта купеческая семья была известна своей щедрой благотворительностью, особенно на строительство и возобновление храмов." },
  { key: "05-13", name: "Отдание праздника Преполовения Пятидесятницы", kind: "feast", desc: "Преполовение Пятидесятницы, тж. Преполовение Господне или Преполовение (греч. &Mu;&epsilon;&sigma;&omicron;&pi;&epsilon;&nu;&tau;&eta;&kappa;&omicron;&sigma;&tau;ή, англ." },
  { key: "05-13", name: "Ап. Иакова Зеведеева", kind: "saint", desc: "Ап. Иаков Зеведеев (ок. 42/44 г.), брат ап. Иоанна Богослова, был рыбаком, призванным Христом. Входил в число ближайших учеников, присутствуя при важнейших событиях: воскрешении дочери Иаира, Преображении и в Гефсиманском саду." },
  { key: "05-13", name: "Обретение мощей свт. Никиты, затворника Печерского, епископа Новгородского", kind: "saint", desc: "Святитель Никита, епископ Новгородский, в молодые годы поступил в Киево-Печерский монастырь и вскоре пожелал уйти в затвор. Игумен предупреждал его о преждевременности такого подвига для молодого инока, но он, понадеявшись на свои силы, не послушался." },
  { key: "05-13", name: "свт. Игнатия (Брянчанинова), епископа Кавказского", kind: "saint", desc: "Святитель Игнатий (в миру Дмитрий Александрович Брянчанинов) родился 5 февраля 1807 г. в родовом имении отца, селе Покровском Вологодской губернии. Мать родила Дмитрия после продолжительного бесплодия, по горячей молитве и путешествии по окрестным святым местам.", lifeId: "ignatiy-bryanchaninov" },
  { key: "05-13", name: "Свт. Доната, епископа Еврии", kind: "saint", desc: "Святитель Донат жил в царствование святого благоверного царя Феодосия Великого (379–397) и был епископом в городе Эврии. Недалеко от этого города в местечке Сориа находился вредоносный источник воды." },
  { key: "05-13", name: "сщмч. Василия, епископа Амасийского", kind: "saint", desc: "Священномученик Василий, епископ Амасийский, жил в начале IV века в понтийском городе Амасии. Он поддерживал и утешал христиан, страдавших от гонений язычников." },
  { key: "05-13", name: "мч. Максима", kind: "saint", desc: "Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Сообщить об ошибке' или Ctrl+Enter." },
  { key: "05-13", name: "Собор святых Ставропольской митрополии", kind: "feast", desc: "Поименный список собора святых Ставропольской митрополии утвержден решением Священного Синода 24 июля 2025 года (журнал № 69). Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделит" },
  { key: "05-14", name: "Прор. Иеремии", kind: "saint", desc: "Святой пророк Иеремия, один из четырех великих ветхозаветных пророков, сын священника Хелкии из города Анафофа близ Иерусалима, жил за 600 лет до Рождества Христова при иудейском царе Иосии и четырех его преемниках." },
  { key: "05-14", name: "прп. Пафнутия Боровского, игумена", kind: "saint", desc: "Преподобный Пафнутий Боровский родился в 1394 году в селе Кудинове, недалеко от Боровска, и при Крещении был назван Парфением. Его отец Иоанн был сыном крестившегося татарина-баскака Мартина, мать Парфения носила имя Фотиния." },
  { key: "05-14", name: "Сщмч. Макария, митрополита Киевского", kind: "saint", desc: "Священномученик Макарий, митрополит Киевский, был ранее архимандритом Виленского Свято-Троицкого монастыря. В 1495 году, после смерти Киевского митрополита Ионы (Глезны), был избран и рукоположен на его место собором святителей: Вассианом Владимирским, Лукою Полоцким, Вассианом Туровским и Ионою Луцким." },
  { key: "05-14", name: "прп. Герасима Болдинского", kind: "saint", desc: "Прп. Герасим Болдинский (1490-1554) – русский подвижник XVI века. Начав монашеский путь под руководством прп. Даниила Переяславского, он 26 лет подвизался в Горицком монастыре, после чего ушел в смоленские леса." },
  { key: "05-14", name: "прмч. Ваты Персиянина", kind: "saint", desc: "Мученик Вата, монах, жил в IV веке, происходил из Персии и подвизался там в одном из монастырей. Во время гонения на христиан, воздвигнутого персидским царем, святой мученик был убит в городе Низивии за исповедание веры Христовой." },
  { key: "05-14", name: "блгв. Тамары, царицы Грузинской", kind: "saint", desc: "Святая Тамара [1] (1184–1213 гг.), грузинская царица, была дочерью Георгия III от красавицы Бурдухан. При ее матери христианство уже распространилось в разных частях Грузии." },
  { key: "05-14", name: "Мц. Нины Кузнецовой", kind: "saint", desc: "Великая сия тайна есть – как выбирает человек путь жизни духовной, как обретает душа пути к рекам воды живой, текущим в жизнь вечную, и, испив из их чистых источников, уже не желает вернуться к призрачным ценностям мира сего." },
  { key: "05-14", name: "Царевококшайская (Мироносицкая)", year: "1647", kind: "saint", desc: "Из известных в настоящее время чудотворных икон Божией Матери только три иконы вырезаны на камне: Жировицкая, явившаяся в 1470 году; Леснинская, обретенная в 1683 году и «Мироносицкая»." },
  { key: "05-14", name: "Андрониковская", kind: "saint", desc: "Андрониковская икона Божией Матери, известная также под именами Монемвасийской и Греческой, – родовая святыня греческого императора Андроника III Палеолога, по преданию, одна из написанных апостолом и евангелистом Лукой." },
  { key: "05-14", name: "Нечаянная Радость", kind: "saint", desc: "На иконе Божией Матери «Нечаянная Радость» изображен человек, молящийся на коленях перед иконой Пресвятой Богородицы. Иконографическим сюжетом для образа послужило предание об исцелении некоего юноши от плотской страсти через святой образ В" },
  { key: "05-15", name: "Свт. Афанасия Великого, архиепископа Александрийского", kind: "saint", desc: "Святой Афанасий родился в Александрии; мать его, подобно Анне, которая привела сына своего Самуила в храм Господень ( 1Цар.1:28 ), так же привела его к св." },
  { key: "05-15", name: "Перенесение мощей блгвв. кнн. Российских Бориса и", kind: "saint", desc: "Свв. благоверные князья Борис и Глеб (†1015) ‒ младшие сыновья св. князя Владимира. Воспитанные в христианской вере, они предпочли смерть междоусобной войне: Борис отказался бороться за престол против старшего брата Святополка, а Глеб смиренно принял смерть, зная о судьбе брата." },
  { key: "05-15", name: "Глеба, во Святом Крещении Романа и Давида", kind: "saint", desc: "Свв. благоверные князья Борис и Глеб (†1015) ‒ младшие сыновья св. князя Владимира. Воспитанные в христианской вере, они предпочли смерть междоусобной войне: Борис отказался бороться за престол против старшего брата Святополка, а Глеб смиренно принял смерть, зная о судьбе брата." },
  { key: "05-15", name: "Свт. Афанасия, патриарха Цареградского, Лубенского чудотворца", kind: "saint", desc: "Святитель Афанасий Сидящий, патриарх Константинопольский, родился в 1597 г. в г. Ретимне на о. Крит. Он происходил из знатного греческого рода Пателариев, бывшего в родстве с византийской императорской династией Палеологов." },
  { key: "05-15", name: "прп. Афанасия Сяндемского", kind: "saint", desc: "Ученик преподобного Александра Свирского . Сподобился быть свидетелем благодатного посещения его учителя Пресвятой Девой Богородицей. Преподобный Афанасий начал свои иноческие подвиги на Валааме, а затем в Свирском монастыре." },
  { key: "05-15", name: "блгв. и равноап. царя Бориса, во Святом Крещении Михаила (907), принявшего Крещение со своим народом в IX веке", kind: "saint", desc: "Равноапостольный подвиг его был предсказан ему дядей, святым Бояном. Первые годы правления царя Бориса складывались неудачно. Болгарам приходилось часто воевать с соседними народами, страну посещали голод и мор, и в 860 году Болгария находилась в бедственном состоянии." },
  { key: "05-15", name: "Путивльская", year: "1635", kind: "saint", desc: "Из детального рассмотрения сведений, помещенных в различных литургических и исторических документах о Путивльской иконе Божией Матери, следует, что по крайней мере два образа носили это наименование." },
  { key: "05-16", name: "прп. Феодосия, игумена Киево-Печерского", kind: "saint", desc: "Прпп. Антоний и Феодосий Печерские ‒ основатели русского монашества. Св. Антоний (ок. 983-1073), уроженец Любеча, принял постриг на Афоне, затем вернулся на Русь и поселился в пещере близ Киева (1051 г.).", lifeId: "pecherskie" },
  { key: "05-16", name: "прп. Петра, чудотворца, епископа Аргосского", kind: "saint", desc: "Преподобный Петр чудотворец, епископ Аргосский, жил в IX – начале Х века и происходил от благочестивых родителей. Родители святого Петра, а затем его братья, Павел, Дионис, Платон, и сам святой Петр приняли монашество." },
  { key: "05-16", name: "Свт. Феофана, митрополита Перифеорийского", kind: "saint", desc: "Из жизнеописания святого Феофана, чей день памяти Русская Православная Церковь отмечает 3/16 мая, известно лишь то, что он был митрополитом Перифеорийским и то, что скончался он после 1353 года." },
  { key: "05-16", name: "Сщмч. Николая Беневоленского, пресвитера", kind: "saint", desc: "Священномученик Николай родился 30 марта 1877 года в городе Москве в семье священника Владимира Павловича и его супруги Екатерины Алексеевны Беневоленских [1] ." },
  { key: "05-16", name: "Успение Киево-Печерская", year: "1073", kind: "saint", desc: "Киево-Печерская икона Успения Пресвятой Богородицы - одна из древнейших явленных икон в Русской Православной Церкви. Пресвятая Богородица вручила ее 4-м византийским зодчим , которые в 1073 году принесли икону преподобным Антонию и Феодосию Печерским." },
  { key: "05-16", name: "Печерская", year: "1085", kind: "saint", desc: "Печерская икона Божией Матери с предстоящими преподобными Антонием и Феодосием Печерскими изображает Божию Матерь, сидящую на троне с короной на голове." },
  { key: "05-16", name: "Свенская (Печерская)", year: "1288", kind: "saint", desc: "Свенская Печерская икона Божией Матери имеет 2 празднования: 3 мая, в день кончины преподобного Феодосия Печерского (см. о ней под этим числом), и 17 августа, в день кончины преподобного Алипия Печерского , который ее написал." },
  { key: "05-17", name: "Мц. Пелагии Тарсийской", kind: "saint", desc: "Св. мц. Пелагия Тарсийская, знатная и образованная девушка из Малой Азии, жила в конце III века. Пленившись красотой, император Диоклетиан хотел выдать её замуж за своего наследника." },
  { key: "05-17", name: "сщмч. Еразма, епископа Формийского", kind: "saint", desc: "Святой Еразм [1] с юных лет усердно служил Господу. В зрелые годы он был возведен в сан епископа города Формии (Италия). Во время гонения на христиан императоров Диоклитиана (284–305) и Максимиана (284–305) святой Еразм оставил свою епархию и удалился в Ливанские горы, где скрывался семь лет." },
  { key: "05-17", name: "сщмч. Альвиана, епископа Анейского, и учеников его", kind: "saint", desc: "Святой Альвиан был епископом города Анеи, Асийской области, пострадал за Христа около 304 года в гонение на христиан императоров Диоклитиана и соправителя его – Максимиана." },
  { key: "05-17", name: "сщмч. Сильвана, епископа Газского, и с ним 40 мучеников", kind: "saint", desc: "Святой Сильван происходил из окрестностей города Газы. В миру Сильван был воином. Желая служить Царю Небесному, он принял священство, а потом был рукоположен во епископа Газского." },
  { key: "05-17", name: "Сщмч. Иоанна Васильева, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился в 1886 году в деревне Черная Грязь Осташковского уезда Тверской губернии в семье крестьянина Иакова Васильева. Образование получил в Осташковском духовном училище." },
  { key: "05-17", name: "сщмч. Николая Тохтуева, диакона", kind: "saint", desc: "Священномученик Николай родился 9 мая 1903 года в заводе Бымовский Осинского уезда Пермской губернии [a] в крестьянской семье. Род Тохтуевых происходил от крещеных татар, которые поселились здесь в первой половине XVIII века; это были потомственные кузнецы, отличавшиеся в своем деле большим мастерством." },
  { key: "05-17", name: "Старорусская", kind: "saint", desc: "Старорусская икона Божией Матери называется так потому, что она долгое время находилась в Старой Руссе, куда была принесена греками из Ольвиополя еще в первые времена христианства на Руси." },
  { key: "05-18", name: "Вмц. Ирины Македонской", kind: "saint", desc: "Святая Ирина жила во второй половине I века и была дочерью Ликиния, правителя области Мигдония в Македонии. Еще в юности Ирина поняла суетность язычества и уверовала во Христа." },
  { key: "05-18", name: "Обретение мощей прп. Иакова Железноборовского", kind: "saint", desc: "Скудны и недостаточны сведения о преподобном. До нашего времени дошли лишь известия, что преподобный Иаков, мирское имя которого не сохранилось в летописях (существует версия, что он был крещен Иоанном), родился в XIV столетии в благочестивой и весьма достаточной семье галичских дворян Амосовых." },
  { key: "05-18", name: "прп. Варлаама Серпуховского", kind: "saint", desc: "Сведения о прп. Варлааме сохранила писаная на доске летопись «О зачатии Владычнего монастыря еже есть в Серпухове», до начала XX века хранившаяся в обители." },
  { key: "05-18", name: "прмч. Ефрема Нового, Неа-Макринского чудотворца", kind: "saint", desc: "На побережье Аттики, чуть к северу от порта Рафина, стоит деревня Неа Макри. За ней возвышается гора Амомон, у подножия которой расположен монастырь Благовещения, больше известный православным грекам просто как &ldquo;монастырь святого Ефрема&rdquo;." },
  { key: "05-18", name: "Неупиваемая Чаша", year: "1878", kind: "saint", desc: "Икона Божией Матери «Неупиваемая Чаша» по иконографии относится к типу «Оранта» – Богоматерь изображена с воздетыми вверх руками, перед Ней – Богомладенец, стоящий в чаше." },
  { key: "05-19", name: "Прав. Иова Многострадального", kind: "saint", desc: "Святой праведный Иов жил за 2000–1500 лет до Рождества Христова, в Северной Аравии, в стране Авситидийской, в земле Уц. Жизнь и страдания его описаны в Библии (Книга Иова)." },
  { key: "05-19", name: "Прп. Михея Радонежского", kind: "saint", desc: "Ученик и келейник Сергия Радонежского (&dagger; 1392; память 5/18июля и 25 сентября/8 октября). Под руководством великого старца, подвизаясь в простоте сердца, преподобный Михей достиг такой высокой степени духовной чистоты, что один из все" },
  { key: "05-19", name: "прп. Иова Почаевского, игумена", kind: "saint", desc: "Прп. Иов Почаевский (в миру Иван Железо, XVI–XVII вв.) ‒ игумен Почаевской лавры. С юности посвятил себя монашеской жизни. Активно защищал православие от католического влияния и унии." },
  { key: "05-19", name: "мч. Варвара Луканского, бывшего разбойника", kind: "saint", desc: "Святой мученик Варвар, бывший разбойник, жил в Греции и долгое время совершал разбои, грабежи и убийства. Но Господь, не хотящий смерти грешника, обратил и его к покаянию." },
  { key: "05-20", name: "Предпразднство Вознесения Господня", kind: "feast", desc: "Вознесение Иисуса Христа на небо – одно из главных событий Священной истории. После Вознесения видимое земное присутствие Христа уступает место Его невидимому пребыванию в Церкви." },
  { key: "05-20", name: "Воспоминание явления на небе Креста Господня в Иерусалиме", year: "351", kind: "feast", desc: "По кончине первого христианского, благоверного и благочестивого царя Константина Великого, царский престол занял сын его Констанций [1] , который уклонился в злочестивую ересь Ария, хулившего Сына Божия [2] ." },
  { key: "05-20", name: "Мч. Акакия сотника", kind: "saint", desc: "Святой мученик Акакий, живший в III столетии, родился в Каппадокии и был сотником Мартисийского полка при военачальнике Фирме. Когда по приказу императора Максимиана Галерия (305–311) началось гонение на христиан, Фирм начал поочередно допрашивать своих воинов о вере." },
  { key: "05-20", name: "Прп. Нила Сорского", kind: "saint", desc: "Родился в 1433 г. Монашеский постриг принял в Успенском Кирилло-Белозерском монастыре. Прожив некоторое время под руководством опытного старца Паисия Ярославова, святой отправился в паломничество по святым местам Востока." },
  { key: "05-20", name: "прпп. Иоанна Зедазнийского и учеников его", kind: "saint", desc: "Преподобный Иоанн Зедазнийский и 12 его учеников: Авив, епископ Некресский, Антоний Марткобский, Давид Гареджийский, Зенон Икалтский, Фаддей Степанцминдский, Исе, епископ Цилканский, Иосиф, епископ Алавердский, Исидор Самтавийский, Михаил У" },
  { key: "05-20", name: "Авива, епископа Некресского", kind: "saint", desc: "Священномученик Авив, епископ Некресский, – один из тринадцати святых сирийских (каппадокийских) отцов, основателей грузинского монашества, пришедших в Грузию в VI веке." },
  { key: "05-20", name: "Антония Марткопского, столпника", kind: "saint", desc: "Святого Антония прозвали Марткопским из-за любви к уединению: в переводе с грузинского «марто мкопи» означает «находящийся в одиночестве». Он был столпником, одним из 12 учеников преподобного Иоанна Зедазнийского, пришедших в Грузию в VI веке и основавших грузинское монашество." },
  { key: "05-20", name: "Давида Гареджийского", kind: "saint", desc: "Один из 13 сирийских отцов, принесших в Грузию «второе Крещение». Проповедовал в Тбилиси, где разоблачил клевету огнепоклонников: коснувшись посохом оклеветавшей его девицы, заставил из ее чрева прозвучать свидетельство о своей невиновности, после чего она родила камень." },
  { key: "05-20", name: "Зенона Икалтойского", kind: "saint", desc: "Преподобный Иоанн Зедазнийский и 12 его учеников: Авив, епископ Некресский, Антоний Марткобский, Давид Гареджийский, Зенон Икалтский, Фаддей Степанцминдский, Исе, епископ Цилканский, Иосиф, епископ Алавердский, Исидор Самтавийский, Михаил У" },
  { key: "05-20", name: "Фаддея Степанцминдского", kind: "saint", desc: "Преподобный Иоанн Зедазнийский и 12 его учеников: Авив, епископ Некресский, Антоний Марткобский, Давид Гареджийский, Зенон Икалтский, Фаддей Степанцминдский, Исе, епископ Цилканский, Иосиф, епископ Алавердский, Исидор Самтавийский, Михаил У" },
  { key: "05-20", name: "Исе (Иессея), епископа Цилканского", kind: "saint", desc: "Преподобный Исе (Иессей), епископ Цилканский, родился в Антиохии Сирийской в благочестивой христианской семье. Еще отроком он почувствовал влечение к духовной жизни, а по достижении совершеннолетия с благословения родителей отправился в одн" },
  { key: "05-20", name: "Иосифа, епископа Алавердского", kind: "saint", desc: "Свт. Иосиф Алавердский, один из 13-и сирийских отцов, пришёл в Грузию в VI веке со своим учителем, св. Иоанном Зедазнийским, и поселился в безлюдной Алавердской степи." },
  { key: "05-20", name: "Исидора Самтавийского", kind: "saint", desc: "Преподобный Иоанн Зедазнийский и 12 его учеников: Авив, епископ Некресский, Антоний Марткобский, Давид Гареджийский, Зенон Икалтский, Фаддей Степанцминдский, Исе, епископ Цилканский, Иосиф, епископ Алавердский, Исидор Самтавийский, Михаил У" },
  { key: "05-20", name: "Михаила Улумбойского", kind: "saint", desc: "Преподобный Иоанн Зедазнийский и 12 его учеников: Авив, епископ Некресский, Антоний Марткобский, Давид Гареджийский, Зенон Икалтский, Фаддей Степанцминдский, Исе, епископ Цилканский, Иосиф, епископ Алавердский, Исидор Самтавийский, Михаил У" },
  { key: "05-21", name: "Вознесение Господне", kind: "great", desc: "Вознесение Иисуса Христа на небо – одно из главных событий Священной истории. После Вознесения видимое земное присутствие Христа уступает место Его невидимому пребыванию в Церкви." },
  { key: "05-21", name: "Апостола и евангелиста Иоанна Богослова", kind: "saint", desc: "Ап. Иоанн Богослов, любимый ученик Христа, был свидетелем ключевых событий Евангелия: Преображения, Тайной Вечери и Распятия. После Распятия он заботился о Богородице до Её Успения." },
  { key: "05-21", name: "прп. Арсения Великого", kind: "saint", desc: "Родился в 354 г. в Риме, в благочестивой христианской семье, давшей ему хорошее воспитание и образование. Изучил сочинения всех риторов и философов и хорошо знал как греческий, так и латинский языки, однако оставил суетную жизнь мирскую и пренебрег еллинским любомудрием, посвящая себя на служение Богу." },
  { key: "05-21", name: "Арсения трудолюбивого", kind: "saint", desc: "Жил в XIV веке. Он назван трудолюбивым потому, что, подвизаясь в пещерах Киево-Печерской обители, он не знал отдыха, и никто никогда не видел его в праздности." },
  { key: "05-21", name: "Пимена постника, игумена (XII), Печерских, в Дальних пещерах", kind: "saint", desc: "Прп. Пимен постник (XII в.) – Киево-Печерский подвижник, известный крайним воздержанием (питался раз в неделю) при постоянном физическом труде и непрестанной молитве." },
  { key: "05-21", name: "мучеников, в долине Ферейдан (Иран) от персов пострадавших (XVII) (Груз.)", kind: "saint", desc: "Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Сообщить об ошибке' или Ctrl+Enter." },
  { key: "05-21", name: "Мч. Никифора Зайцева", kind: "saint", desc: "Мученик Никифор родился 23 марта 1884 года в деревне Пупки Рузского уезда Московской губернии в семье крестьян Петра Константиновича и Марфы Созонтовны Зайцевых." },
  { key: "05-22", name: "Попразднство Вознесения Господня", kind: "feast", desc: "Вознесение Иисуса Христа на небо – одно из главных событий Священной истории. После Вознесения видимое земное присутствие Христа уступает место Его невидимому пребыванию в Церкви." },
  { key: "05-22", name: "Прор. Исаии", kind: "saint", desc: "Жил в VIII веке до Р. X. Царского рода, сын св. пророка Амоса. Был женат, имел сына ( Ис.8:3,18 ). Призван Богом к пророческому служению в царство Озии, царя Иудеи, и пророчествовал около 60-ти лет при Иоафаме, Ахазе, Езекии и Манассии." },
  { key: "05-22", name: "мч. Христофора Ликийского", kind: "saint", desc: "Святой мученик Христофор жил в III веке и пострадал около 250 года, при императоре Декии (249–251). О жизни и чудесах его существует много различных сказаний, память его чтится и в Восточной, и в Западной Церквах." },
  { key: "05-22", name: "Перенесение мощей святителя и чудотворца Николая из Мир Ликийских в Бар", year: "1087", kind: "feast", desc: "Приспе день светлаго торжества,/ град Барский радуется,/ и с ним вселенная вся ликовствует/ песньми и пеньми духовными:/ днесь бо священное торжество/ в пренесение честных и многоцелебных мощей/ святителя и чудотворца Николая,/ якоже солнце" },
  { key: "05-22", name: "прп. Иосифа Оптинского", kind: "saint", desc: "Преподобный Иосиф (в миру Иван Литовкин) родился 2 ноября 1837 года в семье сельского головы Ефима Литовкина и его жены Марии. Четырех лет от роду Ваня потерял отца, а в одиннадцать лишился матери." },
  { key: "05-22", name: "Прп. Шио Мгвимского (VI)", kind: "saint", desc: "Преподобный Шио (Симеон) Мгвимский (от груз. мгвиме – пещера – Печерский) родился в Антиохии Сирской. Родители его были христианами и воспитывали своего сына как единственного наследника." },
  { key: "05-22", name: "Сщмч. Димитрия Воскресенского, пресвитера", kind: "saint", desc: "Протоиерей Димитрий Воскресенский родился 7 сентября 1869 года в селе Урусово Алатырского уезда Симбирской губернии (ныне Мордовской Республики) в семье священника Василия Воскресенского." },
  { key: "05-22", name: "сщмч. Василия Колосова, пресвитера", kind: "saint", desc: "Священномученик Василий родился в 1891 году в селе Спас-Дощатый Зарайского уезда Рязанской губернии в семье священника Алексия Колосова. Окончив в 1915 году Рязанскую Духовную семинарию, Василий Алексеевич до 1927 года служил псаломщиком в " },
  { key: "05-23", name: "Попразднство Вознесения Господня", kind: "feast", desc: "Вознесение Иисуса Христа на небо – одно из главных событий Священной истории. После Вознесения видимое земное присутствие Христа уступает место Его невидимому пребыванию в Церкви." },
  { key: "05-23", name: "Ап. Симона Зилота", kind: "saint", desc: "Ап. Симон Зилот, уроженец Каны Галилейской, был призван Христом после чуда претворения воды в вино на свадьбе в его доме. Прозвище \"Зилот\" («ревнитель») указывает на его ревностную веру." },
  { key: "05-23", name: "Свт. Симона Печерского, епископа Владимирского и Суздальского", kind: "saint", desc: "Святитель Симон Печерский, первый епископ Владимиро-Суздальской земли, родился во второй половине XII в. и подвизался в Киево-Печерском монастыре, где и принял постриг." },
  { key: "05-23", name: "блж. Симона, Христа ради юродивого, Юрьевецкого", kind: "saint", desc: "Блж. Симон Юрьевецкий, Христа ради юродивый, родился в Костромской губернии. С юности оставил дом и поселился в лесах близ села Елнать, приняв подвиг юродства." },
  { key: "05-23", name: "мч. Исихия Антиохийского", kind: "saint", desc: "Святой мученик Исихий Антиохийский жил в царствование Максимиана Галерия (305–311) в городе Антиохии, где занимал высокую и почетную должность при императорском дворе." },
  { key: "05-23", name: "прп. Исидоры юродивой, Тавенской", kind: "saint", desc: "Преподобная Исидора, Христа ради юродивая, подвизалась в Тавенском монастыре (Египет) в IV веке. Девица Исидора приняла на себя подвиг юродства, вела себя как безумная и не вкушала пищи вместе с сестрами обители." },
  { key: "05-23", name: "блж. Таисии Египетской", kind: "saint", desc: "Святая Таисия жила в Египте в V веке. Оставшись сиротой после смерти богатых родителей, она сначала вела благочестивую жизнь, посвящая себя благотворительности и помощи больным." },
  { key: "05-23", name: "Киево-Братская", year: "1654", kind: "saint", desc: "Чудотворная Киево-Братская икона Божией Матери была явлена в 1654 году и первоначально была местной в Борисоглебской церкви города Вышгорода (Киевского)." },
  { key: "05-24", name: "Попразднство Вознесения Господня", kind: "feast", desc: "Вознесение Иисуса Христа на небо – одно из главных событий Священной истории. После Вознесения видимое земное присутствие Христа уступает место Его невидимому пребыванию в Церкви." },
  { key: "05-24", name: "Сщмч. Мокия Амфипольского", kind: "saint", desc: "Святой Мокий был пресвитером в Македонии, в городе Амфиполе. Во время гонения на христиан императора Диоклитиана (284–305) святой Мокий убеждал язычников, собравшихся для празднования языческому божеству Дионису (Бахусу), оставить беззаконн" },
  { key: "05-24", name: "Мефодия, архиепископа", kind: "saint", desc: "Святые равноапостольные первоучители и просветители славянские, братья Кирилл и Мефодий происходили из знатной и благочестивой семьи, жившей в греческом городе Солуни.", lifeId: "kirill-mefodiy" },
  { key: "05-24", name: "Кирилла (869), учителей Словенских", kind: "saint", desc: "Святые равноапостольные первоучители и просветители славянские, братья Кирилл и Мефодий происходили из знатной и благочестивой семьи, жившей в греческом городе Солуни.", lifeId: "kirill-mefodiy" },
  { key: "05-24", name: "равноап. Ростислава, князя Великоморавского", kind: "saint", desc: "Равноапостольный Ростислав, князь Великоморавский, унаследовал княжеский престол в 846 году после смерти своего дяди Моймира I. К этому времени на территории Великоморавского княжества уже проповедовали христианские миссионеры из Греции, Валахии, а также Германии." },
  { key: "05-24", name: "Прп. Софрония, затворника Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Софроний, затворник, подвизался в Дальних (Феодосиевых) пещерах Киево-Печерского монастыря в XIII в. Преподобный Софроний, затворивши себя в темной пещере, ежедневно прочитывал всю Псалтырь и всегда носил на себе власяницу и тяжелый пояс железный." },
  { key: "05-24", name: "сщмч. Иосифа, митрополита Астраханского", kind: "saint", desc: "Священномученик Иосиф, первый митрополит Астраханский, родился в 1597 году в Астрахани в семье родителей Климента и Варвары. Скорби и страдания сопровождали его с юных лет до мученической кончины." },
  { key: "05-24", name: "Собор святых Астраханской митрополии", kind: "feast", desc: "Собор святых Астраханской митрополии празднуется 24 мая, в день памяти сщмч. Иосифа, митрополита Астраханского. Поименный список собора утвержден решением Священного Синода 15 мая 2025 года (журнал № 38)." },
  { key: "05-24", name: "свт. Никодима, архиепископа Сербского", kind: "saint", desc: "Свт. Никодим, архиепископ Сербский (†1324), бывший игумен Хиландарского монастыря на Афоне. Учёный богослов и переводчик: перевёл на сербский язык Иерусалимский устав и дополнил синаксарь поминовением сербских святых." },
  { key: "05-24", name: "Сщмч. Александра (Петровского), архиепископа Харьковского", kind: "saint", desc: "Священномученик Александр родился 23 августа 1851 года в городе Луцке Волынской губернии в семье диакона Феофана Петровского. В 1892 году он окончил четыре класса Волынской Духовной семинарии и в том же году был назначен учителем церковно-п" },
  { key: "05-24", name: "Чолнская", year: "Челнская", kind: "saint", desc: "В окрестностях уездного города Трубчевска Орловской губернии располагался старинный Спасо-Челнский мужской монастырь, основанный (по другим источникам, возобновленный) князем Трубчевским А." },
  { key: "05-24", name: "Умиление Псково-Печерская", year: "1524", kind: "saint", desc: "По преданию, Псково-Печерская икона Божией Матери «Умиление» была написана в 1521 году неким иеромонахом Арсением (Хитрошем) с иконы Божией Матери «Владимирская»." },
  { key: "05-25", name: "Попразднство Вознесения Господня", kind: "feast", desc: "Вознесение Иисуса Христа на небо – одно из главных событий Священной истории. После Вознесения видимое земное присутствие Христа уступает место Его невидимому пребыванию в Церкви." },
  { key: "05-25", name: "Свт. Епифания, епископа Кипрского", kind: "saint", desc: "Святитель Епифаний, епископ Кипрский, жил в IV веке в Финикии, по происхождению был еврей, в молодости получил хорошее образование. Он обратился к христианской вере после того, как увидел одного монаха, по имени Лукиан, отдавшего нищему свою одежду." },
  { key: "05-25", name: "свт. Германа, патриарха Константинопольского", kind: "saint", desc: "Святитель Герман, патриарх Константинопольский, родился в Константинополе в VII веке. Отец его, один из первых сенаторов в Византии, был убит по приказу императора Константина Погоната (668–685), а мальчика Германа оскопили и отдали в церковные клирики, где он глубоко изучил Священное Писание." },
  { key: "05-25", name: "сщмч. Ермогена, патриарха Московского и всея Руси, чудотворца", kind: "saint", desc: "Сщмч. Ермоген (ок. 1530–1612), патриарх Московский и всея Руси, был выдающимся церковным и государственным деятелем Смутного времени. Начав служение священником в Казани, он стал свидетелем обретения Казанской иконы Божией Матери и составил службу в её честь." },
  { key: "05-25", name: "Прп. Дионисия Радонежского, архимандрита", kind: "saint", desc: "Преподобный Дионисий, уроженец г. Ржева, младший современник первого русского патриарха Иова, родился во второй половине XVI века. Получив монастырское воспитание и рано оставшись сиротой, Дионисий принял постриг и вскоре был поставлен настоятелем Старицкого Успенского монастыря." },
  { key: "05-25", name: "Второе обретение мощей прав. Симеона Верхотурского (Меркушинского)", kind: "saint", desc: "Праведный Симеон Верхотурский, дворянин по происхождению, оставил всё и удалился в Сибирь, где вёл жизнь смиренного странника. Он нёс слово Божие местным жителям, в том числе иноверцам-вогулам, и славился своим нестяжательством, смирением и молитвенными подвигами." },
  { key: "05-25", name: "Савина, архиепископа Кипрского", kind: "saint", desc: "Святитель Савин, епископ Кипрский, родился в финикийском городе Ликии. Узнав об известном подвижнике, преподобном Епифании Кипрском, Савин направился к нему и принял иноческий постриг." },
  { key: "05-25", name: "Полувия, епископа Ринокирского", kind: "saint", desc: "Святитель Полувий с молодых лет был учеником святителя Епифания Кипрского, сопровождал его во всех путешествиях и записывал жизнь и чудеса своего учителя." },
  { key: "05-25", name: "мч. Иоанна Валаха (1662)", kind: "saint", desc: "Святой мученик Иоанн Влах, или Валах («Румын»), жил в XVII в. Он был родом из Валашской области Олтении. Однажды валашский господарь (властитель) Михня Водэ решил перебить всех турок, находившихся на территории Валахии в отместку за учиненные в его стране беззакония и грабежи." },
  { key: "05-25", name: "Сщмч. Петра Попова, пресвитера", kind: "saint", desc: "Священномученик Петр родился в 1895 году в селе Никольское Даниловского уезда Ярославской губернии в семье священника Алексея Михайловича Попова. Первоначальное образование Петр получил в Ярославском духовном училище; в 1918 году он окончил" },
  { key: "05-25", name: "мц. Евдокии Мартишкиной", kind: "saint", desc: "Евдокия Петровна Мартишкина родилась 1 марта 1880 года в селе Габлицы (Гиблицы) Касимовского уезда Рязанской губернии в крестьянской семье. Муж Евдокии Петровны был расстрелян в 1918 году как участник крестьянского восстания в Касимовском уезде." },
  { key: "05-26", name: "Попразднство Вознесения Господня", kind: "feast", desc: "Вознесение Иисуса Христа на небо – одно из главных событий Священной истории. После Вознесения видимое земное присутствие Христа уступает место Его невидимому пребыванию в Церкви." },
  { key: "05-26", name: "Прав. Гликерии девы, Новгородской", kind: "saint", desc: "В скудости сведений о святой виден знак потаенности ее жизни и делания. Известно, что она дочь Пантелеимона, старосты улицы Легощей в Великом Новгороде." },
  { key: "05-26", name: "Перенесение мощей прмч. Макария Каневского, игумена Пинского, Переяславского чудотворца", kind: "saint", desc: "Прмч. Макарий Каневский (1605–1678) родился на Волыни. Принял монашество, служил в монастырях Овруча, Пинска и Купятичей. Более 10 лет активно противостоял латино-польскому давлению на православие." },
  { key: "05-26", name: "мч. Александра Римского", kind: "saint", desc: "Святой мученик Александр пострадал за Христа в начале IV века. Он был военным, служил в полку трибуна Тивериана в Риме. Ему шел 18-й год, когда римский император Максимиан Геркул (284–305) издал приказ, чтобы все граждане в определенный день явились в загородный храм Зевса для принесения жертвы." },
  { key: "05-26", name: "свт. Павсикакия, епископа Синадского", kind: "saint", desc: "Святой Павсикакий, епископ Синадский, жил в конце VI века в сирийском городе Апамее. С детства наставленный в христианской вере благочестивыми родителями, он с юных лет стал вести аскетическую жизнь, подвизаясь в молитвах, бдениях и суровом посте." },
  { key: "05-26", name: "свв. Георгия исп.", kind: "saint", desc: "Святой исповедник Георгий пострадал за почитание святых икон в Константинополе в первой половине IX века. Император Феофил принуждал святого Георгия отречься от поклонения святым иконам, но мужественный исповедник отказался исполнить повеле", lifeId: "georgiy" },
  { key: "05-26", name: "Ириною и чадами", kind: "saint", desc: "Святой исповедник Георгий пострадал за почитание святых икон в Константинополе в первой половине IX века. Император Феофил принуждал святого Георгия отречься от поклонения святым иконам, но мужественный исповедник отказался исполнить повеле" },
  { key: "05-26", name: "прп. Евфимия Иверского, Святогорца (1028)", kind: "saint", desc: "Родом грузин, происходил из знатного богатого рода. В детстве он был отдан заложником греческому императору в Константинополь, где с успехом окончил книжное обучение." },
  { key: "05-26", name: "мчч. Черкасских", year: "XX", kind: "saint", desc: "В Хуторах строится единственный в Украине храм во славу новомучеников Черкасских. Черкасская земля, так случилось, дала Украине наибольшее число святых, пострадавших за веру православную в годы коммунистических репрессий." },
  { key: "05-27", name: "Попразднство Вознесения Господня", kind: "feast", desc: "Вознесение Иисуса Христа на небо – одно из главных событий Священной истории. После Вознесения видимое земное присутствие Христа уступает место Его невидимому пребыванию в Церкви." },
  { key: "05-27", name: "Мч. Исидора Хиосского", kind: "saint", desc: "Святой мученик Исидор жил в III веке на острове Хиосе, родом был из Александрии. В первый год правления императора Декия (249–251) был издан указ переписать всех способных служить в войсках Римской империи." },
  { key: "05-27", name: "блж. Исидора, Христа ради юродивого, Ростовского чудотворца", kind: "saint", desc: "Родился в Германии в богатой католической семье. Оставив родительский дом и раздав бедным имущество, св. Исидор, странствуя, обошел многие земли и города." },
  { key: "05-27", name: "Свт. Никиты, затворника Печерского, епископа Новгородского", kind: "saint", desc: "Святитель Никита, епископ Новгородский, в молодые годы поступил в Киево-Печерский монастырь и вскоре пожелал уйти в затвор. Игумен предупреждал его о преждевременности такого подвига для молодого инока, но он, понадеявшись на свои силы, не послушался." },
  { key: "05-27", name: "мч. Максима Азийского", kind: "saint", desc: "Святой мученик Максим пострадал при императоре Декии (249–251). Максим был мирянином и занимался торговлей. Он был благочестивым христианином, многих язычников приводил к вере во Христа Спасителя и убеждал принять крещение." },
  { key: "05-27", name: "прп. Серапиона Синдонита, монаха", kind: "saint", desc: "Преподобный Серапион жил в V веке в Египте, назван Синдонитом, потому что носил лишь грубую льняную одежду, называемую синдоном. С самой юности преподобный жил как птица небесная, не имея пристанища, и по несколько дней не ел, не имея на что купить хлеба." },
  { key: "05-27", name: "свт. Леонтия, патриарха Иерусалимского", kind: "saint", desc: "Святитель Леонтий II (1-я четверть XII в. – 1186/1187) 1 , патриарх Иерусалимский, родился в первой четверти XII века, между 1110 и 1115 годами (или после 1120 года) 2 в северной Македонии в городе в Тивериополе (ныне Струмица)." },
  { key: "05-27", name: "прп. Додо Гареджийского (623) (Груз.)", kind: "saint", desc: "Князь из рода Вачнадзе, ученик св. Давида Гареджийского. Основал монастырь Пресвятой Богородицы в горах Кахетии, где 25 лет был игуменом. Подвизался в узкой расщелине скалы, «молясь с покаянными слезами»." },
  { key: "05-27", name: "Сщмч. Петра Рождествина, пресвитера", kind: "saint", desc: "Священномученик Петр родился 25 июня 1879 года в селе Дмитриевский Погост Коробовской волости Егорьевского уезда Рязанской губернии [1] в семье псаломщика Алексея Михайловича и Александры Алексеевны Рождествиных." },
  { key: "05-27", name: "Теребенская (Теребинская)", year: "1654", kind: "saint", desc: "Время прославления сей чудотворной иконы относится к 1654 году. В 1654 году в Тверской губернии свирепствовала моровая язва. Отчаявшиеся люди искали помощи и заступничества в молитвах святителю Николаю и Божией Матери пред Ее иконой Теребенская." },
  { key: "05-27", name: "Ярославская Печерская", year: "1823", kind: "saint", desc: "Прославилась икона в конце XIX века в Ярославле . Жительница города мещанка Александра Дмитриевна Добычкина стала страдать ломотой в руках и во всех суставах." },
  { key: "05-28", name: "Попразднство Вознесения Господня", kind: "feast", desc: "Вознесение Иисуса Христа на небо – одно из главных событий Священной истории. После Вознесения видимое земное присутствие Христа уступает место Его невидимому пребыванию в Церкви." },
  { key: "05-28", name: "Прп. Пахомия Великого", kind: "saint", desc: "Язычник, обратившийся в христианство. Основал первый общежительный монастырь в Египте по велению Божию. Получил от Ангела устав монашеской жизни. Создал 9 обителей (7000 монахов)." },
  { key: "05-28", name: "свт. Исаии, епископа Ростовского, чудотворца", kind: "saint", desc: "Ученик преподобного Феодосия Печерского, основатель Димитриевского монастыря в Киеве. В 1078 году поставлен епископом Ростовским. Ревностно искоренял язычество, строил храмы, заботился о бедных." },
  { key: "05-28", name: "блгв. царевича Димитрия, Угличского и Московского", kind: "saint", desc: "Младший сын Ивана Грозного. В 8 лет убит в Угличе по приказу Бориса Годунова. Прославлен как невинный страстотерпец. Мощи обретены нетленными (1606), перенесены в Архангельский собор Московского Кремля." },
  { key: "05-28", name: "Прп. Исаии Печерского", kind: "saint", desc: "Подвизался в Киево-Печерской Лавре. Основные подвиги – безмолвие и неустанный труд. Обладал даром побеждать бесовские искушения. Скончался 15 мая 1115 года." },
  { key: "05-28", name: "прп. Пахомия Нерехтского", kind: "saint", desc: "Родился во Владимире. Основал Троице-Сыпанову пустынь под Костромой (1365 г.), где ввел строгий устав. Прославился подвижнической жизнью, даром прозорливости и чудотворений." },
  { key: "05-28", name: "Евфросина (1481) и ученика его", kind: "saint", desc: "Основатель Спасо-Елеазаровского монастыря. Приняв постриг в Снетогорской обители, ушел в пустынь на реку Толву. По явлению трёх святителей основал храм в их честь." },
  { key: "05-28", name: "Серапиона, Псковских", kind: "saint", desc: "Прп. Евфросин (1386–1481) – основатель Спасо-Елеазаровского монастыря, автор уникального скитского устава, подчёркивавшего равенство братии. Прославился крайним аскетизмом, отказался от игуменства." },
  { key: "05-28", name: "обретение мощей прп. Арсения Коневского", kind: "saint", desc: "Новгородский ремесленник, принявший монашество. 3 года подвизался на Афоне, где получил в благословение Коневскую икону Божией Матери. В 1393 г. основал на Ладожском озере Коневский Рождество-Богородичный монастырь." },
  { key: "05-28", name: "прп. Ахиллия, епископа Ларисийского", kind: "saint", desc: "Участник I Вселенского Собора, обличитель арианства. Епископ Лариссы, прославился ученостью и чудотворениями. Ревностно искоренял язычество, строил храмы." },
  { key: "05-28", name: "прп. Давида Гареджийского (VI) (Груз.)", kind: "saint", desc: "Один из 13 сирийских отцов, принесших в Грузию «второе Крещение». Проповедовал в Тбилиси, где разоблачил клевету огнепоклонников: коснувшись посохом оклеветавшей его девицы, заставил из ее чрева прозвучать свидетельство о своей невиновности, после чего она родила камень." },
  { key: "05-29", name: "Отдание праздника Вознесения Господня", kind: "feast", desc: "Вознесение Иисуса Христа на небо – одно из главных событий Священной истории. После Вознесения видимое земное присутствие Христа уступает место Его невидимому пребыванию в Церкви." },
  { key: "05-29", name: "Прп. Феодора Освященного, игумена", kind: "saint", desc: "Юный аристократ, в 14 лет тайно покинувший дом ради монашества. Стал любимым учеником прп. Пахомия Великого, проявив исключительное послушание. В 20 лет, по благословению старца, дерзнул поучать братию – случай беспрецедентный для новоначального инока." },
  { key: "05-29", name: "Перенесение мощей прп. Ефрема Перекомского, игумена, Новгородского чудотворца", kind: "saint", desc: "Прп. Ефрем Перекомский родился в 1412 году в Тверской губернии. С юности вёл аскетическую жизнь, ушёл из дома в Калязинский монастырь, а затем перешёл в обитель прп." },
  { key: "05-29", name: "Кассиана", kind: "saint", desc: "Был учеником преподобного Корнилия Комельского (&dagger; 1537, память 19 мая/1 июня), управлял Комельским монастырем во время ухода преподобного Корнилия на Сурское озеро." },
  { key: "05-29", name: "Лаврентия (1548) Комельских", kind: "saint", desc: "Ученик преподобного Корнилия Комельского (память 19 мая/1 июня). Подвизаясь в трудах, посте и молитвах, преподобный Лаврентий по указанию преподобного Корнилия был поставлен во игумена монастыря." },
  { key: "05-29", name: "сщмч. Александра, епископа Иерусалимского", kind: "saint", desc: "Выдающийся церковный просветитель III века. Ученик Климента Александрийского и друг Оригена. Начав служение епископом во Флавии (Каппадокия), он претерпел гонения при Септимии Севере." },
  { key: "05-29", name: "блж. отроковицы Музы Римляныни", kind: "saint", desc: "Блаженная Муза жила в V веке. Известно, что она отличалась благонравием. О ней рассказал святой Григорий Двоеслов , папа Римский, своему архидиакону Петру то, что слышал от брата Музы, Прова." },
  { key: "05-29", name: "прпп. отцов, в Лавре св. С а ввы убиенных", year: "614", kind: "saint", desc: "Лавра прп. Саввы Освященного находится недалеко от Иерусалима. В 614 году в правление имп. Ираклия (620–641) она подверглась набегу персов, которые ошибочно считали, что монастырь обладает большими сокровищами." },
  { key: "05-29", name: "свт. Георгия II, епископа Митиленского", kind: "saint", desc: "Святитель Георгий был поставлен епископом Митиленским в 820–829 годах, во время иконоборческих смут. Скончался в 842 году в Митилене. В XII веке святые мощи его видел русский игумен Даниил, путешествовавший по Востоку и оставивший описание этого путешествия.", lifeId: "georgiy" },
  { key: "05-29", name: "мч. Вукашина (1943)", kind: "saint", desc: "В Клепце находилась старинная, начала XVI века, церковь святого апостола Луки – задушбина (задушбины – храмы и монастыри, строившиеся на пожертвования верующих, во спасение души, – «за душу») известных сербских храмостроителей Милорадовичей" },
  { key: "05-30", name: "Ап. от 70-ти Андроника, епископа", kind: "saint", desc: "Ап. Андроник и св. Иуния – сродники апостола Павла (Рим.16:7), одни из первых уверовавших во Христа. Ап. Андроник стал епископом Паннонии, но их миссия вышла далеко за пределы епархии." },
  { key: "05-30", name: "св. Иунии", kind: "saint", desc: "Ап. Андроник и св. Иуния – сродники апостола Павла (Рим.16:7), одни из первых уверовавших во Христа. Ап. Андроник стал епископом Паннонии, но их миссия вышла далеко за пределы епархии." },
  { key: "05-30", name: "Прп. Евфросинии, в миру Евдокии, вел. кн. Московской", kind: "saint", desc: "Супруга блгв. кн. Дмитрия Донского. С юных лет отличалась глубоким благочестием. Во время Куликовской битвы молилась за победу русского войска, а после победы построила в Кремле храм Рождества Пресвятой Богородицы." },
  { key: "05-30", name: "прмч. Адриана Ондрусовского", kind: "saint", desc: "Прмч. Адриан Ондрусовский, в миру дворянин Андрей Завалишин, оставил имение после встречи с прп. Александром Свирским. Приняв постриг на Валааме, он основал Никольскую обитель на Ладожском озере." },
  { key: "05-30", name: "свт. Стефана, патриарха Константинопольского", kind: "saint", desc: "Сын императора Василия Македонянина, брат Льва Мудрого. Приняв священный сан, в 886 году взошел на патриарший престол после свт. Фотия. Прославился милосердием: защищал вдов и сирот, отличался строгим воздержанием." },
  { key: "05-31", name: "День Святой Троицы. Пятидесятница", kind: "great", desc: "Христианская Пятидесятница имеет свой ветхозаветный прототип — одноименный иудейский праздник &Pi;&epsilon;&nu;&tau;&eta;&kappa;&omicron;&sigma;&tau;ή — Пятидесятница." },
  { key: "05-31", name: "Память святых отцов семи Вселенских Соборов", kind: "feast", desc: "Семь Вселенских Соборов – это становление Церкви, её догматов, определение основ христианского вероучения. Поэтому очень важно, что в самых сокровенных, догматических, законодательных вопросах Церковь никогда не брала в высшие авторитеты мнение одного человека." },
  { key: "05-31", name: "прп. Макария Алтайского", kind: "saint", desc: "Выдающийся миссионер, переводчик Библии, основатель Алтайской духовной миссии. Сын смоленского священника, выпускник Петербургской духовной академии. Приняв монашество, 14 лет проповедовал среди алтайских народов, крестив около 1400 человек." },
  { key: "05-31", name: "Прав. Иоанна Кормянского, пресвитера", kind: "saint", desc: "Белорусский священник. Строгий аскет, после паломничества в Киево-Печерскую лавру соблюдал монашеские правила. Обладал даром прозорливости и чудотворений – изгонял бесов крестным знамением." },
  { key: "05-31", name: "Св. Михаила Виноградова исп., пресвитера", kind: "saint", desc: "Священник из Московской губернии, сын священника. Окончил Московскую духовную семинарию (1895). Служил в Зосимовой пустыни, затем в селе Лисинцево. В 1931 году арестован за \"антиколхозную агитацию\" – на самом деле за создание церковного хора и проповеди, вдохновлявшие верующих." },
  { key: "05-31", name: "сщмч. Василия Крылова, пресвитера", kind: "saint", desc: "В 1937 году арестован по ложному обвинению в контрреволюционной деятельности. На допросах категорически отрицал свою вину и не признавал ложные показания свидетелей." },
];
